def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    reqs = [WATER_REQ]
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            reqs.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    total_agents = 1 + len(alive)
    avg_req = sum(reqs) / float(len(reqs)) if reqs else WATER_REQ
    expected_winners = max(1, int(supply / avg_req))
    scarcity = expected_winners < total_agents

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev

    urgent = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1

    if urgent:
        bid = max(63.0, highest_prev + 1.5)
        return float(min(budget, bid, DAILY_SALARY))

    if scarcity:
        if highest_prev >= 68:
            bid = 64.0 if pressured else 46.0
        elif highest_prev >= 55:
            bid = max(52.0, min(66.0, highest_prev + 1.0))
        elif highest_prev > 0:
            bid = max(38.0, min(58.0, second_prev + 2.0))
        else:
            bid = 42.0 if pressured else 30.0
    else:
        if pressured:
            bid = 34.0 if highest_prev < 60 else 52.0
        else:
            bid = 18.0 if highest_prev >= 68 else 24.0

    if budget < bid:
        bid = budget

    if hp >= 8 and no_water_days == 0 and budget < DAILY_SALARY * 3:
        bid = min(bid, budget * 0.45)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # If we are already in critical condition, prioritize survival.
    if my_status['hp'] is not None and my_status['hp'] <= 2:
        return min(float(my_status['budget']), DAILY_SALARY * 0.95)

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only.
    prev_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            prev_bids.append(float(b))

    # Estimate competitive pressure from yesterday.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else 0.0

    # Supply pressure: if supply is low, water is scarce; we should bid more.
    # Map supply to a [0,1] scarcity factor.
    if MAX_SUPPLY - MIN_SUPPLY <= 0:
        scarcity = 0.5
    else:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
        if scarcity < 0.0:
            scarcity = 0.0
        if scarcity > 1.0:
            scarcity = 1.0

    # Base bid: moderate, scaled by scarcity.
    base = DAILY_SALARY * (0.45 + 0.25 * scarcity)

    # If someone bid very high yesterday, they likely expect to secure water again.
    # We try to outbid just enough, but cap to avoid bankruptcy.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Cindy-like behavior: bid close to but slightly above likely threshold.
        target = min(highest_prev_bid, DAILY_SALARY * 1.0)
        # Add a small increment to beat them.
        bid = target + 5.0
    elif highest_prev_bid >= DAILY_SALARY * 0.65:
        # Eric-like: bid around the leader but not fully.
        bid = max(base, second_prev_bid + 8.0, highest_prev_bid * 0.92)
    else:
        # Low pressure: bid near base; still ensure we can win if needed.
        bid = base

    # If we have many no-water days, increase bid.
    no_water_days = float(my_status.get('no_water_days', 0.0) or 0.0)
    if no_water_days >= 2:
        bid *= 1.25
    if no_water_days >= 4:
        bid *= 1.45

    # Final clamp by budget.
    budget = float(my_status['budget'])
    if budget <= 0.0:
        return 0.0

    # Ensure bid is at least a small positive amount when budget allows.
    bid = float(bid)
    if bid < 1.0:
        bid = 1.0
    if bid > budget:
        bid = budget

    return bid

